import {generate,totals,goals,weekdays,allergens,validateProfile} from './engine.js';
import {KEY,fresh,today,dayIndex,saveProfile,dayRecord,recordTraining,parseBackup,persist,upgradePlans} from './store.js';
const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#dialog');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>Number(n).toLocaleString('pt-BR',{maximumFractionDigits:1});
const prettyDate=s=>new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{day:'numeric',month:'long'});
let catalog,state=fresh(),tab='today',date=today(),plan,formStep=-1,draft=null,installPrompt=null,toastTimer;
const profile=()=>state.profiles[state.activeProfile];
const currentPlan=()=>generate(catalog,profile());
const getRecord=()=>state.days[date]??{profileId:state.activeProfile,water:0,meals:Array.from({length:4},()=>({option:0,done:false})),training:null};
const displayedPlan=()=>generate(catalog,state.profiles[getRecord().profileId]??profile(),dayIndex(date));
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5500);}
function commit(change){const next=structuredClone(state);try{change(next);persist(next);state=next;plan=currentPlan();return true;}catch(e){notify(e.message);return false;}}
const icons={today:'<rect x="4" y="5" width="16" height="16" rx="3"/><path d="M8 3v4m8-4v4M4 10h16m-12 5h3m2 0h3"/>',food:'<path d="M5 3v6a3 3 0 006 0V3M8 3v18m11 0V3c-4 2-5 8 0 9M5 6h6"/>',training:'<path d="M3 9v6m3-9v12m12-12v12m3-9v6M6 12h12"/>',profile:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0116 0v2"/>'};
function render(){
 if(formStep>=0){renderForm();return;}
 $('#nav').hidden=!state.activeProfile;
 if(!state.activeProfile){welcome();return;}
 $('#nav').innerHTML=Object.entries({today:'Hoje',food:'Comer',training:'Treinar',profile:'Perfil'}).map(([key,label])=>`<button data-tab="${key}" class="${key===tab?'active':''}" ${key===tab?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${icons[key]}</svg>${label}</button>`).join('');
 plan=currentPlan();({today:renderToday,food:renderFood,training:renderTraining,profile:renderProfile}[tab])();
}
function welcome(){
 app.innerHTML=`<section class="hero"><div><span class="pill">Uma rotina que cabe na sua vida</span><h1>Seu próximo passo.<br>Um rumo<br><em>mais leve.</em></h1><p class="lead">Alimentação, movimento e pequenas conquistas. Organize sua rotina a partir do seu perfil, no seu próprio ritmo.</p><div class="actions"><button class="primary" data-action="start">Começar meu plano <span aria-hidden="true">→</span></button><button class="text-button" data-action="install">Como instalar no iPhone</button></div><p class="small">Sem conta. Seus dados ficam neste aparelho.</p></div><div class="hero-visual" aria-label="Ilustração de um exemplo de rotina, sem dados pessoais"><div class="orbit"></div><div class="preview"><p class="eyebrow">Pequenos passos, todos os dias</p><h3>Sua rotina, mais leve.</h3><div class="preview-date"><span>S<br>09</span><span class="active">T<br>10</span><span>Q<br>11</span><span>Q<br>12</span><span>S<br>13</span><span>S<br>14</span><span>D<br>15</span></div><div class="preview-meal"><span class="meal-icon" aria-hidden="true">◒</span><div><strong>Café da manhã</strong><br><small>Principal + 2 alternativas</small></div></div><div class="preview-water">Um lembrete para cuidar de você<div class="water-dots" aria-hidden="true">${'<i></i>'.repeat(7)}</div></div><div class="preview-training"><span>Movimento de hoje<br><strong>Um passo de cada vez</strong></span><span class="pill">Leve</span></div></div><div class="floating-note"><strong>Consistência vale mais.</strong><br>Sua evolução começa com o possível.</div></div></section>
 <section class="features" aria-label="O que você encontra"><div class="feature"><div class="feature-number">01</div><div><h3>Comer com mais clareza</h3><p>Refeições com porções e duas alternativas próximas em energia e proteína, quando compatíveis com seu perfil.</p></div></div><div class="feature"><div class="feature-number">02</div><div><h3>Movimento no seu ritmo</h3><p>De 1 a 6 treinos por semana, descansos distribuídos e um começo leve para quem está voltando.</p></div></div><div class="feature"><div class="feature-number">03</div><div><h3>Ver as pequenas conquistas</h3><p>Registre água, refeições, peso e treino. Seu diário acompanha o que você realmente fez.</p></div></div></section>
 <section class="install-card"><div><h2>Rumo também no seu iPhone.</h2><p>Adicione à Tela de Início e abra como um app. Sem precisar da App Store.</p></div><button class="secondary" data-action="install">Ver como instalar ↗</button></section>
 <p class="disclaimer">Para adultos. As sugestões são educativas e não substituem nutricionista, médico ou profissional de educação física. Condições clínicas e restrições que exigem avaliação individual mantêm acesso ao diário, sem plano automático inadequado.</p><button class="text-button" data-action="privacy">Privacidade e fontes</button><button class="text-button" data-action="import">Restaurar backup web</button>`;
}
function header(kicker,title,description='',datePicker=true){return `<div class="page-head"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${datePicker?`<label class="date-input"><span class="small muted">Data do diário</span><input type="date" id="diary-date" value="${date}"></label>`:''}</div>`;}
function renderToday(){
 const r=getRecord(),p=displayedPlan(),w=p.workouts[state.week][dayIndex(date)],done=r.meals.filter(m=>m.done).length;
 app.innerHTML=header('Seu dia, um passo de cada vez',`${date===today()?'Olá'+(profile().name?', '+esc(profile().name):'')+'.':prettyDate(date)}`,`${weekdays[dayIndex(date)]}, ${prettyDate(date)} · semana ${state.week+1}`)+
 `<div class="stats"><div class="stat"><strong>${done}/4</strong><span>refeições registradas</span></div><div class="stat"><strong>${num(r.water/1000)} L</strong><span>água registrada</span></div><div class="stat"><strong>${p.target?num(p.target):'—'}</strong><span>${p.target?'kcal · referência estimada':'sem meta automática'}</span></div></div>
 <div class="grid"><section class="card"><div class="card-title"><h2>Movimento do dia</h2><span class="pill">${w.kind==='rest'?'Recuperar':w.kind==='guide'?'Orientação':w.minutes+' min'}</span></div><h3>${esc(w.title)}</h3><p class="muted small" style="margin-top:12px">${esc(w.effort)}</p>${r.training?`<p class="small" style="margin-top:16px">${r.training.done?'✓ Atividade registrada':'Registro salvo'} · esforço ${r.training.effort}/10${r.training.pain?' · relatou dor':''}</p>`:''}<button class="secondary" data-tab="training" style="margin-top:22px">Ver treino e diário →</button></section>
 <section class="card"><div class="card-title"><h2>Uma pausa para água</h2><span class="small muted">Registro livre</span></div><div class="water-value">${num(r.water)} <span>ml</span></div><p class="small muted">Sem meta universal: sua necessidade é individual.</p><div class="actions"><button class="primary" data-action="water" data-amount="250">+ 250 ml</button><button class="secondary" data-action="water" data-amount="-250" ${r.water===0?'disabled':''}>− 250 ml</button></div></section></div>
 <section class="card" style="margin-top:20px"><div class="card-title"><h2>Seu peso ao longo do tempo</h2><span class="small muted">Sem pressa</span></div>${weightChart()}<form id="weight-form" class="weight-row"><label>Peso em kg<input name="weight" type="number" min="30" max="350" step="0.1" placeholder="Ex.: 80,5" inputmode="decimal" required></label><button class="primary" type="submit">Registrar em ${prettyDate(date)}</button></form><p class="small muted" style="margin-top:15px">O peso do cadastro não é uma pesagem no diário. Registrar aqui não recalcula o plano; para isso, edite seu perfil.</p></section>
 <section class="card"><div class="card-title"><h2>Seu histórico</h2><button class="text-button" data-tab="profile">Backup e perfil</button></div>${history()}</section>
 <p class="disclaimer">Pare a atividade com dor, inchaço, instabilidade, tontura ou mal-estar. Dor no peito, desmaio ou falta de ar intensa exigem atendimento. As sugestões não substituem avaliação individual.</p>`;
}
function weightChart(){
 const weights=[...state.weights].sort((a,b)=>a.date.localeCompare(b.date)).slice(-20);
 if(!weights.length)return '<p class="empty">Sua primeira pesagem começa aqui. Acompanhe a tendência com o tempo.</p>';
 let chart='';if(weights.length>1){const min=Math.min(...weights.map(w=>w.value)),max=Math.max(...weights.map(w=>w.value));const points=weights.map((w,i)=>[10+i*480/(weights.length-1),80-(w.value-min)/Math.max(1,max-min)*60]);chart=`<svg class="chart" viewBox="0 0 500 100" role="img" aria-label="Tendência das últimas pesagens. Valores na lista abaixo."><polyline points="${points.map(p=>p.join(',')).join(' ')}"/>${points.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="4"/>`).join('')}</svg>`;}
 return chart+`<ul class="history-list">${weights.slice(-5).reverse().map(w=>`<li><span>${prettyDate(w.date)}</span><strong>${num(w.value)} kg</strong></li>`).join('')}</ul>`;
}
function history(){const dates=Object.keys(state.days).sort().reverse().slice(0,14);if(!dates.length)return '<p class="empty">Quando você registrar uma refeição, água ou treino, o dia aparece aqui.</p>';return `<ul class="history-list">${dates.map(d=>{const r=state.days[d];return `<li><button data-date="${d}">${prettyDate(d)}</button><span>${r.meals.filter(m=>m.done).length}/4 refeições · ${num(r.water)} ml${r.training?.done?' · treino ✓':''}</span></li>`;}).join('')}</ul>`;}
function adaptationView(p,kind){const lines=p.adaptation?.[kind];return lines?`<details class="card"><summary>Por que este ${kind==='diet'?'cardápio':'treino'} foi escolhido?</summary><ul class="small muted">${lines.map(line=>`<li>${esc(line)}</li>`).join('')}</ul></details>`:'';}
function renderFood(){
 const p=displayedPlan(),r=getRecord();
 app.innerHTML=header('Alimentação com possibilidades','Seu jeito de comer.',p.target?`Referência educativa: ${num(p.target)} kcal/dia · porções aproximadas`:'Seu diário alimentar continua disponível')+
 `<div class="note">Cada refeição tem uma principal e duas alternativas próximas em energia e proteína, quando há opções compatíveis. Escolha uma refeição completa. Leia rótulos: os filtros não certificam ausência de alérgenos ou contaminação cruzada.</div><div style="height:20px"></div>${adaptationView(p,'diet')}<div class="grid">${p.meals.map((m,slot)=>{
 const choice=r.meals[slot].option,option=m.options[choice];
 return `<section class="card"><div class="meal-label">${esc(m.time)}</div><div class="card-title"><h2>${esc(m.label)}</h2>${r.meals[slot].done?'<span class="pill">Registrada</span>':''}</div>${!option?`<p class="note warning">${esc(m.reason)}</p>`:`<div class="meal-tabs" role="group" aria-label="Opções para ${esc(m.label)}">${m.options.map((o,i)=>`<button class="${choice===i?'selected':''}" aria-pressed="${choice===i}" data-action="choice" data-slot="${slot}" data-option="${i}">${i===0?'Principal':'Alternativa '+i}</button>`).join('')}</div><h3>${esc(option.name??option.title??'Refeição')}</h3><ul class="ingredients">${option.items.map(i=>`<li><span>${esc(catalog.foods[i.food].name)}</span><span>${num(i.g)} g<br>${esc(i.portion)}</span></li>`).join('')}</ul><div class="macros">${totals(catalog.foods,option).slice(0,4).map((n,i)=>`${num(n)} ${['kcal','g proteína','g carboidrato','g gordura'][i]}`).join(' · ')}</div>`}<label class="check" style="margin-top:20px"><input type="checkbox" data-meal="${slot}" ${r.meals[slot].done?'checked':''}>${option?'Registrei esta refeição':'Registrar refeição orientada fora do app'}</label></section>`;
 }).join('')}</div><p class="disclaimer">Composição aproximada: TACO/Unicamp. Medidas caseiras e preparo alteram os valores. Não são exigidos suplementos. Horários são sugestões de organização.</p>`;
}
function workoutView(w){return `<div class="card-title"><div><p class="eyebrow" style="margin-bottom:8px">${esc(w.effort)}</p><h2>${esc(w.title)}</h2></div>${w.minutes?`<span class="pill">${w.minutes} min</span>`:''}</div>${w.steps.map((s,i)=>`<div class="step"><span class="step-number">${i+1}</span><div><h3>${esc(s.name)}</h3><div class="dose">${esc(s.dose)}</div><p>${esc(s.detail)}</p></div></div>`).join('')}`;}
function renderTraining(){
 const p=displayedPlan(),r=getRecord(),w=p.workouts[state.week][dayIndex(date)],t=r.training;
 const original=t?generate(catalog,state.profiles[t.profileId]).workouts[t.week][dayIndex(date)]:null;
 app.innerHTML=header('Movimento e recuperação','Encontre seu ritmo.',`${state.profiles[r.profileId]?.frequency??profile().frequency??5} treinos por semana · semana ${state.week+1} de 4. Avanço manual.`)+
 `${adaptationView(p,'training')}<div class="split" style="margin-bottom:18px"><label>Semana das sugestões<select id="week">${[0,1,2,3].map(i=>`<option value="${i}" ${state.week===i?'selected':''}>Semana ${i+1}</option>`).join('')}</select></label><span class="small muted" style="max-width:260px;margin-left:20px">Repita a semana se houver desconforto ou recuperação difícil.</span></div><div class="week-strip">${weekdays.map((name,i)=>`<button class="week-day ${dayIndex(date)===i?'active':''} ${p.workouts[state.week][i].kind==='rest'?'rest':''}" data-weekday="${i}">${name.slice(0,3)}<strong>${p.workouts[state.week][i].kind==='rest'?'Pausa':p.workouts[state.week][i].kind==='swim'?'Nadar':p.workouts[state.week][i].kind==='strength'?'Força':p.workouts[state.week][i].kind==='guide'?'Guia':'Andar'}</strong></button>`).join('')}</div>
 <div class="training-layout"><section class="card">${t?'<p class="eyebrow">Sugestão para esta data</p>':''}${workoutView(w)}</section><div><section class="card"><h2>Diário do treino</h2><p class="small muted" style="margin-top:10px">Registre o que aconteceu. Um dia leve também conta.</p>${t?`<div class="saved-record" style="margin-top:20px"><strong>Registro salvo · semana ${t.week+1}</strong><p>${esc(original.title)}</p><p>Perfil da época: ${esc(goals[state.profiles[t.profileId].goal])}. Editar a anotação preserva esse contexto.</p><details><summary>Ver atividade do registro</summary>${workoutView(original)}</details></div>`:''}<form id="training-form"><label class="check"><input type="checkbox" name="done" ${t?.done?'checked':''}>${(original??w).kind==='rest'?'Registrei meu descanso':'Concluí a atividade registrada'}</label><label>Esforço percebido · de 0 a 10<select name="effort">${Array.from({length:11},(_,i)=>`<option value="${i}" ${(t?.effort??2)===i?'selected':''}>${i}${i===0?' · repouso':i===10?' · máximo':''}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="pain" ${t?.pain?'checked':''}>Senti dor ou instabilidade</label><label>Anotação (opcional)<textarea name="note" maxlength="500" placeholder="Como você se sentiu?">${esc(t?.note??'')}</textarea></label><button class="primary" style="margin-top:18px" type="submit" ${date>today()?'disabled':''}>Salvar registro</button>${date>today()?'<p class="small muted" style="margin-top:12px">Consulta de data futura. Registre a atividade quando esse dia chegar.</p>':''}</form></section><div class="note warning">Não avance com dor, inchaço ou instabilidade. Interrompa e procure avaliação. Este é um começo de condicionamento, sem garantia de aprovação ou índices oficiais de TAF.</div></div></div>`;
}
function renderProfile(){const p=profile();app.innerHTML=header('Seu ponto de partida','Um plano com a sua cara.',goals[p.goal],false)+
 `<div class="grid"><section class="card"><div class="card-title"><h2>Seu perfil</h2><button class="text-button" data-action="edit">Editar</button></div>${summary(p)}<p class="small muted" style="margin-top:22px">Alterações geram uma revisão do perfil. Registros anteriores preservam seu contexto.</p></section><section class="card"><h2>Seus dados ficam com você.</h2><p class="muted small" style="margin-top:16px">Neste navegador ou app instalado, sem conta e sem sincronização automática. Limpar os dados do site, trocar de aparelho ou remover o app pode apagar seu diário.</p><div class="actions"><button class="primary" data-action="export">Exportar backup web</button><button class="secondary" data-action="import">Restaurar backup web</button></div><p class="small muted" style="margin-top:14px">O arquivo não é criptografado e inclui dados de saúde. Guarde em local privado. O formato web é separado do backup Android.</p></section></div>
 <section class="install-card"><div><h2>Seu Rumo, na Tela de Início.</h2><p>Veja como instalar no iPhone ou em outros aparelhos.</p></div><button class="secondary" data-action="install">Guia de instalação ↗</button></section>
 <section class="card" style="margin-top:20px"><h2>Como as sugestões funcionam</h2><p class="muted small" style="margin-top:16px">Cálculos locais, sem inteligência artificial ou análise clínica de texto. Estimativa energética de Mifflin–St Jeor, catálogo TACO e limites operacionais descritos no projeto. Objetivos e necessidades podem exigir ajuste profissional.</p>${!plan.dietAllowed?`<p class="note warning" style="margin-top:18px">${esc(plan.dietReason)}</p>`:''}${!plan.exerciseAllowed?`<p class="note warning" style="margin-top:18px">${esc(plan.exerciseReason)}</p>`:''}<button class="text-button" data-action="privacy" style="margin-top:15px">Privacidade, limites e fontes</button><details><summary>Revisões anteriores de hoje</summary>${state.archivedDays.length?state.archivedDays.slice(-10).reverse().map(a=>`<p class="small muted">${prettyDate(a.date)} · ${esc(goals[state.profiles[a.record.profileId].goal])} · ${a.record.meals.filter(m=>m.done).length}/4 refeições · ${num(a.record.water)} ml</p>`).join(''):'<p class="small muted">Nenhuma revisão arquivada.</p>'}</details></section><button class="text-button" data-action="erase">Apagar todos os dados deste navegador</button>`;}
function summary(p){return `<dl class="profile-summary">${[['Nome',p.name||'Não informado'],['Objetivo',goals[p.goal]],['Idade',p.age+' anos'],['Altura',num(p.height)+' cm'],['Peso de referência',num(p.weight)+' kg'],['Atividade',{low:'Pouco ativo',light:'Leve',moderate:'Moderada',high:'Muito ativo'}[p.activity]],['Alimentação',{common:'Comum',vegetarian:'Vegetariana',vegan:'Vegana'}[p.diet]],['Treino',`${p.place==='home'?'Em casa':'Academia'} · ${p.experience==='beginner'?'iniciante/retorno':'regular'}`],['Frequência',`${p.frequency??5} treinos por semana`],['Natação no sábado',p.swim?'Sim, com acesso e domínio':'Não'],['Saúde',{none:'Sem condição informada',joint:'Histórico articular, sem dor atual',clinical:'Necessita avaliação individual'}[p.health]],['Restrições',p.restrictions.map(r=>allergens[r]).join(', ')||'Nenhuma selecionada'],['Outras observações',[p.restrictionNote,p.healthNote].filter(Boolean).join(' · ')||'Nenhuma']].map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl>`;}
const defaults=()=>({frequency:5,planVersion:2,name:'',age:'',height:'',weight:'',sex:'unspecified',activity:'low',goal:'lose',health:'none',diet:'common',experience:'beginner',place:'home',swim:false,meatLunch:false,restrictions:[],healthNote:'',restrictionNote:''});
function beginForm(edit=false){draft=edit?structuredClone(profile()):defaults();formStep=0;render();window.scrollTo(0,0);}
const field=(name,label,type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(draft[name])}" ${extra}></label>`;
const select=(name,label,options)=>`<label>${label}<select name="${name}">${Object.entries(options).map(([v,l])=>`<option value="${v}" ${String(draft[name])===v?'selected':''}>${l}</option>`).join('')}</select></label>`;
function renderForm(){
 $('#nav').hidden=true;const names=['Seu ponto de partida','Seu movimento','Sua alimentação','Saúde e revisão'];let content='';
 if(formStep===0)content=`<div class="field-grid">${field('name','Como podemos chamar você? (opcional)','text','maxlength="60" autocomplete="given-name" class="wide"')}${field('age','Idade (anos)','number','min="18" max="100" step="1" required inputmode="numeric"')}${field('height','Altura (cm)','number','min="130" max="220" step="0.1" required inputmode="decimal"')}${field('weight','Peso (kg)','number','min="30" max="350" step="0.1" required inputmode="decimal"')}${select('sex','Parâmetro de sexo para a estimativa',{unspecified:'Prefiro não informar',male:'Masculino',female:'Feminino'})}<div class="wide">${select('goal','Qual é seu foco?',goals)}</div></div><p class="small muted" style="margin-top:18px">A geração automática é para adultos. Sem informar sexo, você pode usar o diário sem meta calórica automática.</p>`;
 if(formStep===1)content=`<div class="field-grid">${select('activity','Atividade no dia a dia',{low:'Pouco ativo',light:'Leve',moderate:'Moderada',high:'Muito ativo'})}${select('experience','Experiência atual',{beginner:'Iniciante ou voltando agora',regular:'Treino regularmente'})}${select('place','Onde vai treinar?',{home:'Em casa',gym:'Na academia'})}${select('frequency','Quantas vezes quer treinar por semana?',{1:'1 vez por semana',2:'2 vezes por semana',3:'3 vezes por semana',4:'4 vezes por semana',5:'5 vezes por semana',6:'6 vezes por semana'})}</div><label class="check" style="margin-top:20px"><input type="checkbox" name="swim" ${draft.swim?'checked':''}>Sei nadar, tenho acesso à piscina supervisionada e quero natação aos sábados.</label><div class="note" style="margin-top:14px">A quantidade de sessões e os descansos acompanham sua escolha. Se escolher natação, uma das sessões será no sábado. Quatro semanas iniciais, com avanço manual.</div>`;
 if(formStep===2)content=`${select('diet','Seu padrão alimentar',{common:'Comum',vegetarian:'Vegetariano',vegan:'Vegano'})}<label class="check" style="margin-top:14px"><input type="checkbox" name="meatLunch" ${draft.meatLunch?'checked':''}>Prefiro comer carne somente no almoço.</label><fieldset class="fieldset"><legend>Restrições e alérgenos a excluir</legend><div class="checks">${Object.entries(allergens).map(([k,v])=>`<label class="check"><input type="checkbox" name="restriction" value="${k}" ${draft.restrictions.includes(k)?'checked':''}>${v}</label>`).join('')}</div></fieldset><label style="margin-top:18px">Outra restrição (opcional)<textarea name="restrictionNote" maxlength="500" placeholder="Descreva o que não foi contemplado">${esc(draft.restrictionNote)}</textarea></label><p class="small muted" style="margin-top:15px">Outras restrições precisam de revisão profissional antes de gerar dieta. Confira rótulos e contaminação cruzada. Suplementos não são necessários.</p>`;
 if(formStep===3)content=`${select('health','Qual opção descreve sua saúde?',{none:'Não tenho condição ou sintoma relevante',joint:'Histórico articular, sem dor ou instabilidade atual',clinical:'Condição, dor/sintoma atual, gestação ou amamentação'})}<label style="margin-top:20px">Outras informações de saúde ou medicamentos (opcional)<textarea name="healthNote" maxlength="500" placeholder="Qualquer informação que mereça avaliação individual">${esc(draft.healthNote)}</textarea></label><div class="note warning" style="margin-top:18px">Dor atual, doença, gestação/amamentação, medicamentos ou situações não contempladas pedem avaliação profissional. Nesse caso, você pode usar o diário sem receber exercícios ou dieta clínica automáticos.</div><details style="margin-top:15px"><summary>Revisar os dados anteriores</summary>${summary(draft)}</details><label class="check" style="margin-top:14px"><input type="checkbox" name="consent" required>Entendo que as sugestões são educativas e que meus dados ficam neste navegador. Li os limites e quero criar meu perfil local.</label>`;
 app.innerHTML=`<div class="form-layout"><p class="form-step">SEU PERFIL · ETAPA ${formStep+1} DE 4</p><div class="form-progress"><i style="width:${(formStep+1)*25}%"></i></div><h1>${names[formStep]}.</h1><p class="intro">Uma rotina possível começa conhecendo você.</p><form id="profile-form"><div class="card">${content}<div id="form-error" role="alert"></div></div><div class="form-actions"><button type="button" class="secondary" data-action="form-back">${formStep?'← Voltar':'Cancelar'}</button><button type="submit" class="primary">${formStep===3?'Criar meu plano':'Continuar →'}</button></div></form><p class="disclaimer">Sem conta e sem envio do seu cadastro. Não há sincronização entre aparelhos. <button type="button" class="text-button" data-action="privacy">Privacidade e fontes</button></p></div>`;
}
function readDraft(){const form=$('#profile-form');if(!form)return;const data=new FormData(form);for(const key of ['name','age','height','weight','sex','goal','activity','experience','place','frequency','diet','health','restrictionNote','healthNote'])if(data.has(key))draft[key]=['age','height','weight','frequency'].includes(key)?Number(data.get(key)):String(data.get(key)).trim();if(formStep===1)draft.swim=data.has('swim');if(formStep===2){draft.meatLunch=data.has('meatLunch');draft.restrictions=data.getAll('restriction');}}
function showModal(title,content){dialog.innerHTML=`<button class="dialog-close" data-action="close" aria-label="Fechar">×</button><h2 id="dialog-title">${title}</h2>${content}`;dialog.showModal();}
function showInstall(){
 const installed=matchMedia('(display-mode: standalone)').matches||navigator.standalone;
 showModal('Seu Rumo na Tela de Início.',`${installed?'<p class="note" style="margin-top:20px">Você já abriu o Rumo como um app instalado.</p>':''}<p class="muted small" style="margin-top:15px">No iPhone ou iPad, a instalação é feita pelo menu do navegador. Este botão mostra o caminho.</p><ol class="install-steps"><li><strong>Abra este site no Safari.</strong><p>Se estiver em uma rede social ou outro app, copie o link e abra no Safari.</p></li><li><strong>Toque em Compartilhar <span class="share-symbol" aria-hidden="true"><svg viewBox="0 0 24 28"><path d="M8 10H4v15h16V10h-4M12 17V2M7 7l5-5 5 5"/></svg></span></strong><p>Em alguns layouts, abra primeiro o menu da página e depois Compartilhar.</p></li><li><strong>Escolha “Adicionar à Tela de Início”.</strong><p>Role a lista para encontrar. Se faltar, toque em Editar Ações e inclua essa opção.</p></li><li><strong>Confirme o nome Rumo e toque em Adicionar.</strong><p>Se aparecer “Abrir como App da Web”, deixe ativado. Abra depois pelo ícone na Tela de Início.</p></li></ol><div class="note">De preferência, instale antes de cadastrar seu perfil. O app instalado pode ter armazenamento separado do Safari. Se já começou, exporte um backup web em Perfil e restaure pelo ícone instalado.</div><details style="margin-top:16px"><summary>Android ou computador</summary><p class="small muted">No Chrome ou Edge, procure “Instalar aplicativo” ou “Adicionar à tela inicial” no menu do navegador. O nome pode variar.</p>${installPrompt?'<button class="primary" data-action="native-install" style="margin-top:14px">Instalar Rumo</button>':''}<p class="small muted" style="margin-top:12px">No Android, você também pode usar o <a href="https://github.com/saulomendess06-art/rumo-dieta-treino/releases/tag/v1.3.0" target="_blank" rel="noopener noreferrer">aplicativo APK</a>. Os dados não são sincronizados com esta versão web.</p></details><p class="small muted" style="margin-top:16px">Para usar offline, aguarde o aviso “Pronto para usar offline” neste aparelho. Limpar dados ou remover o app pode apagar o diário: mantenha seu backup privado.</p><p class="modal-links"><a href="https://support.apple.com/pt-br/guide/iphone/iphea86e5236/ios" target="_blank" rel="noopener noreferrer">Instruções oficiais da Apple ↗</a></p>`);
}
function privacy(){showModal('Privacidade e cuidado.',`<p class="small muted" style="margin-top:20px">Seu cadastro e diário são gravados somente no armazenamento deste navegador. Não enviamos esses dados a um servidor. Não usamos contas, anúncios, fontes remotas, análises de uso ou IA. A hospedagem recebe as requisições normais dos arquivos do site, que podem incluir IP e dados técnicos.</p><p class="small muted">Em aparelho compartilhado, outras pessoas com acesso ao navegador podem ver o perfil. Os dados e backups locais não são criptografados pelo app. Exportar um backup é uma ação sua; guarde-o de forma privada. Limpar dados do navegador ou trocar de origem/aparelho não transfere o histórico.</p><p class="small muted">As sugestões não são diagnóstico, prescrição clínica, tratamento ou reabilitação. Sem metas automáticas para casos fora da cobertura. Pare com dor e procure avaliação. Não há garantia de emagrecimento, ganho muscular ou aprovação em TAF.</p><div class="divider"></div><h3>Fontes e regras</h3><p class="small muted" style="margin-top:12px">Estimativas alimentares locais, porções aproximadas e rotina inicial de quatro semanas. As alternativas são comparadas em energia e proteína; outros nutrientes podem diferir.</p><ul class="small"><li><a href="https://www.nepa.unicamp.br/taco/tabela.php?ativo=tabela" target="_blank" rel="noopener noreferrer">TACO — NEPA/Unicamp</a></li><li><a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener noreferrer">Equação de Mifflin–St Jeor</a></li><li><a href="https://github.com/saulomendess06-art/rumo-dieta-treino/blob/main/docs/modelo.md" target="_blank" rel="noopener noreferrer">Regras, limites e documentação do Rumo</a></li></ul>`);}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);}
function importBackup(){showModal('Restaurar backup web.',`<p class="small muted" style="margin-top:18px">A restauração substitui os dados deste navegador. Exporte seu backup atual antes. Aceita arquivos Rumo Web de até 8 MB; o backup Android tem formato diferente.</p><form id="import-form" style="margin-top:20px"><label>Arquivo de backup<input type="file" name="backup" accept=".json,application/json" required></label><label class="check"><input name="replace" type="checkbox" required>Entendo que os dados locais serão substituídos.</label><button type="submit" class="primary">Restaurar arquivo</button><p id="import-error" role="alert" class="small" style="margin-top:12px"></p></form>`);}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button,a.brand');if(!b)return;
 if(b.matches('a.brand')){e.preventDefault();if(formStep>=0)return;tab='today';render();window.scrollTo(0,0);return;}
 if(b.dataset.tab){tab=b.dataset.tab;render();window.scrollTo(0,0);return;}
 if(b.dataset.date){date=b.dataset.date;render();window.scrollTo(0,0);return;}
 if(b.dataset.weekday!==undefined){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+Number(b.dataset.weekday)-dayIndex(date));const next=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;date=next;render();return;}
 if(date>today()&&['water','choice'].includes(b.dataset.action)){notify('Data futura: consulte as sugestões e registre quando o dia chegar.');return;}
 switch(b.dataset.action){
 case 'start':beginForm();break;case 'edit':beginForm(true);break;case 'install':showInstall();break;case 'privacy':privacy();break;case 'close':dialog.close();break;
 case 'native-install':if(installPrompt){await installPrompt.prompt();installPrompt=null;dialog.close();}break;
 case 'form-back':readDraft();if(formStep===0){formStep=-1;draft=null;}else formStep--;render();window.scrollTo(0,0);break;
 case 'water':if(commit(s=>{const r=dayRecord(s,date);r.water=Math.max(0,Math.min(20000,r.water+Number(b.dataset.amount)));}))render();break;
 case 'choice':if(commit(s=>{dayRecord(s,date).meals[Number(b.dataset.slot)].option=Number(b.dataset.option);}))render();break;
 case 'export':download('rumo-web-backup-'+today()+'.json',JSON.stringify(state,null,2));notify('Backup preparado. Guarde o arquivo em local privado.');break;
 case 'import':importBackup();break;
 case 'erase':showModal('Apagar os dados locais?',`<p class="small muted" style="margin-top:18px">Esta ação remove o perfil e todo o diário deste navegador. Exporte um backup antes se quiser manter uma cópia.</p><div class="actions"><button class="secondary" data-action="close">Cancelar</button><button class="danger" data-action="erase-confirm">Apagar definitivamente</button></div>`);break;
 case 'erase-confirm':try{localStorage.removeItem(KEY);state=fresh();date=today();dialog.close();render();notify('Dados locais apagados.');}catch{notify('Não foi possível apagar os dados neste navegador.');}break;
 case 'update':location.reload();break;
 }
});
document.addEventListener('change',e=>{
 if(e.target.id==='diary-date'){if(!e.target.value){notify('Escolha uma data válida.');e.target.value=date;return;}date=e.target.value;render();}
 if(e.target.id==='week'){if(commit(s=>{s.week=Number(e.target.value);}))render();}
 if(e.target.dataset.meal!==undefined){if(date>today()){e.target.checked=false;notify('Registre a refeição quando esse dia chegar.');return;}if(commit(s=>{dayRecord(s,date).meals[Number(e.target.dataset.meal)].done=e.target.checked;}))render();}
});
document.addEventListener('submit',async e=>{
 e.preventDefault();const form=e.target,data=new FormData(form);if(date>today()&&['weight-form','training-form'].includes(form.id)){notify('Data futura: o diário está disponível a partir desse dia.');return;}
 if(form.id==='profile-form'){
 readDraft();if(formStep<3){formStep++;render();window.scrollTo(0,0);return;}
 try{validateProfile(draft);if(commit(s=>saveProfile(s,draft,today()))){formStep=-1;draft=null;date=today();tab='today';render();window.scrollTo(0,0);notify('Perfil salvo. Seu próximo passo começa aqui.');navigator.storage?.persist?.().catch(()=>{});}}catch(error){$('#form-error').className='form-error';$('#form-error').textContent=error.message;}
 }
 if(form.id==='weight-form'){const value=Number(data.get('weight'));if(commit(s=>{s.weights=s.weights.filter(w=>w.date!==date);s.weights.push({date,value});s.weights.sort((a,b)=>a.date.localeCompare(b.date));})) {render();notify('Pesagem salva no diário.');}}
 if(form.id==='training-form'){const fields={done:data.has('done'),effort:Number(data.get('effort')),pain:data.has('pain'),note:String(data.get('note')).trim()};if(commit(s=>recordTraining(s,date,fields))){render();notify(fields.pain?'Registro salvo. Interrompa a atividade e procure avaliação da dor.':'Registro de treino salvo.');}}
 if(form.id==='import-form'){try{const file=data.get('backup');if(file.size>8*1024*1024)throw Error('O arquivo excede 8 MB.');const next=parseBackup(await file.text());upgradePlans(next);persist(next);state=next;formStep=-1;tab='today';date=today();dialog.close();render();notify('Backup web restaurado.');}catch(error){$('#import-error').textContent=error.message;}}
});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
window.addEventListener('storage',e=>{if(e.key===KEY){showModal('Dados alterados em outra aba.',`<p class="small muted" style="margin-top:20px">Recarregue para usar a versão mais recente do seu diário e evitar sobrescrever alterações de outra aba.</p><button class="primary" data-action="update" style="margin-top:20px">Recarregar agora</button>`);}});
async function setupOffline(){
 if(!('serviceWorker'in navigator)){ $('#offline-status').textContent='Uso offline indisponível neste navegador';return;}
 try{const reg=await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;
 const ready=async()=>{const cache=await caches.open('rumo-web-1.3.1');const found=await cache.match(new URL('./plan.json',location.href));$('#offline-status').textContent=found?'● Pronto para usar offline neste aparelho':'Conecte para concluir o preparo offline';};await ready();navigator.serviceWorker.addEventListener('controllerchange',ready);
 reg.addEventListener('updatefound',()=>{reg.installing?.addEventListener('statechange',()=>{if(reg.waiting&&navigator.serviceWorker.controller){notify('Atualização disponível. Feche todas as abas do Rumo e abra novamente.');}});});
 }catch{$('#offline-status').textContent='Uso online · não foi possível preparar o modo offline';}
}
async function start(){try{const response=await fetch('./plan.json');if(!response.ok)throw Error('Não foi possível carregar o catálogo. Conecte à internet para abrir pela primeira vez.');catalog=await response.json();
 const raw=localStorage.getItem(KEY);if(raw){state=parseBackup(raw);if(upgradePlans(state))persist(state);}else {const probe='rumo.storage-test';localStorage.setItem(probe,'1');localStorage.removeItem(probe);}render();setupOffline();
 }catch(error){app.innerHTML=`<section class="card"><h1 style="font-size:2rem">Precisamos de um instante.</h1><p style="margin-top:20px">${esc(error.message)}</p><p class="small muted" style="margin-top:14px">Se houver dados anteriores, eles foram preservados. Use uma janela normal e confira o espaço disponível.</p><div class="actions"><button class="primary" data-action="update">Tentar novamente</button><button class="secondary" id="recover">Salvar cópia dos dados</button></div></section>`;$('#recover').onclick=()=>{try{download('rumo-web-recuperacao.json',localStorage.getItem(KEY)??'{}');}catch{notify('O armazenamento não está acessível.');}};$('#offline-status').textContent='Aguardando carregamento';}}
start();
